package cn.local.rainreminder;
import android.content.Context;import org.json.*;import java.time.*;import java.util.regex.*;
final class SchoolExams {
 static final class Result {JSONArray events=new JSONArray();int unavailable;}
 static Result parse(JSONArray rows)throws Exception{Result result=new Result();for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);String time=r.optString("time").replace('年','-').replace('月','-').replace("日","").replace('：',':');Matcher date=Pattern.compile("(\\d{4})-(\\d{1,2})-(\\d{1,2})").matcher(time),hours=Pattern.compile("(\\d{1,2}):(\\d{2})\\s*[-—~～至]\\s*(\\d{1,2}):(\\d{2})").matcher(time);if(r.optString("title").isEmpty()||!date.find()||!hours.find()){result.unavailable++;continue;}try{LocalDate day=LocalDate.of(Integer.parseInt(date.group(1)),Integer.parseInt(date.group(2)),Integer.parseInt(date.group(3)));LocalTime from=LocalTime.of(Integer.parseInt(hours.group(1)),Integer.parseInt(hours.group(2))),to=LocalTime.of(Integer.parseInt(hours.group(3)),Integer.parseInt(hours.group(4)));if(!to.isAfter(from))throw new IllegalArgumentException();long start=day.atTime(from).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli(),end=day.atTime(to).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();JSONObject event=Agenda.create("考试 · "+r.getString("title"),r.optString("place"),start,end,false);event.put("source","schoolExam").put("examKind",r.optString("kind")).put("lead",1440).put("scanLead",-1).put("liveReminder",false);result.events.put(event);}catch(RuntimeException invalid){result.unavailable++;}}return result;}
}
